function useDomTranslation(lang:string){
  useEffect(()=>{
    const dict=langUi[lang]||langUi.en;
    document.documentElement.lang=lang;
    const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
    const nodes:Text[]=[]; let n:Node|null; while((n=walker.nextNode())) nodes.push(n as Text);
    nodes.forEach(node=>{
      const parent=node.parentElement;
      if(parent?.closest('script,style')) return;
      const original=node.parentElement?.getAttribute('data-ks-original-text') ?? node.nodeValue ?? '';
      node.parentElement?.setAttribute('data-ks-original-text', original);
      const key=original.trim();
      if(dict[key]){const startIdx=original.indexOf(key);node.nodeValue=original.slice(0,startIdx)+dict[key]+original.slice(startIdx+key.length)}
      else node.nodeValue=original;
    });
    document.querySelectorAll<HTMLElement>('[placeholder],[title],[aria-label]').forEach(el=>['placeholder','title','aria-label'].forEach(a=>{
      const originalAttr=el.getAttribute(`data-ks-original-${a}`) ?? el.getAttribute(a);
      if(originalAttr!==null) el.setAttribute(`data-ks-original-${a}`,originalAttr);
      const original=el.getAttribute(`data-ks-original-${a}`);
      if(original && dict[original]) el.setAttribute(a,dict[original]); else if(original) el.setAttribute(a,original);
    }));
  },[lang]);
}

function App() {
  const lang=read('kisanLang','en');
  useDomTranslation(lang);
  useEffect(() => { document.title = `${APP_NAME} — Smart Farming`; }, []);
  return <Routes>
    <Route path="/" element={<Landing />} />
    <Route path="/login" element={<Login />} />
    <Route path="/register" element={<Register />} />
    <Route path="/success" element={<Success />} />
    <Route path="/dashboard/*" element={<Protected><Dashboard /></Protected>} />
    <Route path="*" element={<Navigate to="/" replace />} />
  </Routes>;
}
function Protected({ children }: { children: React.ReactNode }) { return read('kisanAuth', false) ? <>{children}</> : <Navigate to="/login" replace />; }

function Logo() {
  return <Link className="logo" to="/"><span className="logo-mark"><Leaf size={23} /></span><span><strong>{APP_NAME}</strong><small>Smart Farming • Better Tomorrow</small></span></Link>;
}
function Feature({ icon, title, text }: { icon: React.ReactNode; title: string; text: string }) {
  return <div className="feature"><div className="feature-icon">{icon}</div><div><strong>{title}</strong><span>{text}</span></div></div>;
}
function Landing() {
  return <div className="page landing"><header className="public-nav"><Logo /><div className="nav-actions"><Link className="btn btn-ghost" to="/login">Login</Link><Link className="btn btn-primary" to="/register">Create Farmer Account</Link></div></header>
    <main><section className="hero"><div className="hero-copy"><div className="eyebrow"><Leaf size={15}/> Built for Indian Farmers</div><h1>Better prices. Smarter selling. <span>Higher farm confidence.</span></h1><p>{APP_NAME} brings mandi prices, buyer discovery, profit planning, logistics, documents, schemes and weather into one simple farmer-first dashboard.</p><div className="hero-actions"><Link className="btn btn-primary btn-lg" to="/login">Open Farmer Dashboard <ArrowRight size={18}/></Link><Link className="btn btn-soft btn-lg" to="/register">Register Now</Link></div><div className="trust-row"><div><strong>12+</strong><span>Farmer tools</span></div><div><strong>Live-ready</strong><span>API architecture</span></div><div><strong>Mobile-first</strong><span>Field friendly</span></div></div></div>
      <div className="hero-art"><div className="sun-orb"></div><div className="field-card"><div className="mini-top"><span>Today on {APP_NAME}</span><span className="live-dot">DEMO</span></div><div className="mini-price"><span>Soybean</span><strong>₹4,850 <em>/ qtl</em></strong><b>+5.2%</b></div><div className="mini-bars">{[42,57,47,74,67,88,95].map((h,i)=><span key={i} style={{height:`${h}%`}} />)}</div><div className="mini-foot"><span><MapPin size={14}/> Wardha</span><span><CloudSun size={14}/> 31°C</span></div></div><div className="farm-silhouette"><div className="hill"></div><div className="tractor"><Tractor size={80}/></div></div></div>
    </section><section className="feature-strip"><Feature icon={<BarChart3/>} title="Price Discovery" text="Compare price, distance and net return."/><Feature icon={<Wallet/>} title="Profit Planning" text="Know revenue, costs and estimated margin."/><Feature icon={<Truck/>} title="Transport Optimization" text="Estimate distance and shared transport savings."/><Feature icon={<MessageCircle/>} title="Easy Support" text="Reach support on WhatsApp."/></section></main></div>;
}

function Login() {
  const nav = useNavigate();
  const [mobile, setMobile] = useState(''); const [password, setPassword] = useState(''); const [show, setShow] = useState(false);
  const [mode, setMode] = useState<'password'|'otp'>('password'); const [otp, setOtp] = useState(''); const [otpSent, setOtpSent] = useState(false);
  const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [otpMessage, setOtpMessage] = useState('');
  const validMobile = /^[6-9]\d{9}$/.test(mobile);
  const doLogin = () => { const registered = read<Farmer|null>('kisanFarmer', null); save('kisanAuth', true); save('kisanFarmer', registered && registered.mobile === mobile ? registered : {...initialFarmer, mobile}); nav('/dashboard'); };
  const submit = (e: React.FormEvent) => { e.preventDefault(); setError(''); if (!validMobile) return setError('Enter a valid 10-digit Indian mobile number starting with 6, 7, 8 or 9.'); if (mode==='password' && !password.trim()) return setError('Password is required.'); if (mode==='otp' && (!otpSent || otp !== DEMO_OTP)) return setError(`Enter the valid OTP. Demo OTP: ${DEMO_OTP}`); setBusy(true); setTimeout(()=>{doLogin();setBusy(false);},350); };
  const sendOtp = () => { setError(''); if(!validMobile) return setError('Enter a valid Indian mobile number first.'); setOtpSent(true); setOtpMessage(`Demo OTP sent. Use ${DEMO_OTP} to continue.`); };
  return <div className="auth-shell"><div className="auth-side"><Logo/><div><span className="eyebrow">Farmer access</span><h2>Your farm, market and money—together.</h2><p>Simple access designed for field use and older farmers.</p></div><div className="auth-side-card"><ShieldCheck size={24}/><span><strong>Demo mode</strong> OTP and password workflows work locally for testing.</span></div></div><div className="auth-main"><div className="auth-card"><div className="mobile-logo"><Logo/></div><div className="auth-head"><h1>Farmer Login</h1><p>Choose password or mobile OTP login.</p></div><div className="tabs"><button className={mode==='password'?'active':''} onClick={()=>{setMode('password');setError('')}}>Password</button><button className={mode==='otp'?'active':''} onClick={()=>{setMode('otp');setError('')}}>Mobile OTP</button></div>
    <form onSubmit={submit} className="form"><label>Mobile Number<div className="input-wrap"><Phone size={18}/><input inputMode="numeric" value={mobile} maxLength={10} onChange={e=>setMobile(e.target.value.replace(/\D/g,'').slice(0,10))} placeholder="9876543210"/><span className="counter">{mobile.length}/10</span></div></label>
      {mode==='password' ? <label>Password<div className="input-wrap"><Lock size={18}/><input type={show?'text':'password'} value={password} onChange={e=>setPassword(e.target.value)} placeholder="Enter any password"/><button type="button" className="icon-btn" onClick={()=>setShow(!show)}>{show?<EyeOff size={17}/>:<Eye size={17}/>}</button></div></label> : <><div className="otp-row"><label className="grow">OTP<div className="input-wrap"><Smartphone size={18}/><input inputMode="numeric" maxLength={6} value={otp} onChange={e=>setOtp(e.target.value.replace(/\D/g,'').slice(0,6))} placeholder="6-digit OTP"/></div></label><button type="button" className="btn btn-soft otp-btn" onClick={sendOtp}>{otpSent?'Resend OTP':'Send OTP'}</button></div>{otpMessage&&<div className="success-box">{otpMessage}</div>}</>}
      {error&&<div className="error-box"><CircleAlert size={16}/>{error}</div>}<button className="btn btn-primary btn-full" disabled={busy}>{busy?<><RefreshCw className="spin" size={17}/> Signing in…</>:<>Login <ArrowRight size={17}/></>}</button></form><div className="divider"><span>New farmer?</span></div><Link className="btn btn-soft btn-full" to="/register">Create Account / Register</Link><Link className="back-link" to="/"><ArrowLeft size={15}/> Back to home</Link>
  </div></div></div>;
}

const label = (k: string) => ({name:'Full Name',mobile:'Mobile Number',farmerId:'Aadhaar / Farmer ID',dob:'Date of Birth',gender:'Gender',address:'Address',village:'Village',district:'District',state:'State',landArea:'Land Area',ownership:'Land Ownership',category:'Farmer Category',mainCrop:'Main Crop',bank:'Bank Account',ifsc:'IFSC Code'} as Record<string,string>)[k] || k;
function Register() {
  const nav = useNavigate(); const [step,setStep]=useState(0); const [err,setErr]=useState(''); const [confirm,setConfirm]=useState('');
  const [data,setData]=useState<Farmer>({...initialFarmer,name:'',mobile:'',farmerId:'',dob:'',gender:'',address:'',village:'',district:'',state:'Maharashtra',landArea:'',ownership:'Owned',mainCrop:'',bank:'',ifsc:'',category:'',password:''});
  const [files,setFiles]=useState<Record<string,string>>({}); const set=(k:keyof Farmer,v:string)=>setData({...data,[k]:v});
  const fields = [['Aadhaar Document','aadhaar'],['7/12 Extract','satbara'],['8A Extract','eightA'],['Land Ownership Document','ownership']];
  const validate=()=>{
    if(step===0){if(!data.name.trim())return 'Full Name is required.'; if(!/^[6-9]\d{9}$/.test(data.mobile))return 'Enter a valid 10-digit Indian mobile number.'; if(!data.farmerId.trim())return 'Aadhaar / Farmer ID is required.'; if(!data.dob)return 'Date of Birth is required.'; if(!data.gender)return 'Gender is required.'; if(!data.password?.trim())return 'Password is required.'; if((data.password||'').length<4)return 'Password must be at least 4 characters.'; if(data.password!==confirm)return 'Passwords do not match.';}
    if(step===1){for(const k of ['address','village','district','state','landArea','ownership','category','mainCrop'] as (keyof Farmer)[]) if(!String(data[k]).trim())return `${label(k)} is required.`; if(Number(data.landArea)<=0)return 'Land area must be greater than 0.';}
    if(step===2){if(!data.bank.trim())return 'Bank account details are required.';if(!/^[A-Z]{4}0[A-Z0-9]{6}$/i.test(data.ifsc))return 'Enter a valid IFSC code.';}
    if(step===3){for(const [display] of fields)if(!files[display])return `${display} must be uploaded.`;}
    return '';
  };
  const next=()=>{const e=validate();if(e)return setErr(e);setErr('');if(step<3)setStep(step+1);else{save('kisanFarmer',data);save('kisanAuth',true);save('kisanDocs',defaultDocs.map(d=>({...d,status:d.name==='Aadhaar Card'?'Uploaded':d.status})));nav('/success')}};
  const FilePick=({display}:{display:string})=><div className="upload-box"><FileText/><div><strong>{display}</strong><span>{files[display]||'PDF, JPG or PNG • max 5 MB'}</span></div><label className="btn btn-soft btn-sm"><Upload size={15}/> Choose<input hidden type="file" accept=".pdf,.jpg,.jpeg,.png" onChange={e=>{const f=e.target.files?.[0];if(!f)return;if(f.size>5*1024*1024)return setErr('File must be 5 MB or smaller.');setFiles({...files,[display]:f.name});}}/></label></div>;
  return <div className="register-page"><header className="public-nav"><Logo/><Link className="back-link" to="/login"><ArrowLeft size={15}/> Already have an account?</Link></header><main className="register-main"><div className="register-header"><span className="eyebrow">Farmer onboarding</span><h1>Create your {APP_NAME} account</h1><p>Complete your details once. Your dashboard keeps the rest simple.</p></div><div className="stepper">{['Personal','Farm','Bank','Documents'].map((s,i)=><div key={s} className={'step '+(i===step?'active ':'')+(i<step?'done':'')}><span>{i<step?<CheckCircle2 size={17}/>:i+1}</span><b>{s}</b></div>)}</div><div className="register-card">
    {step===0&&<Section title="Personal Details"><div className="grid2"><Field label="Full Name" value={data.name} onChange={v=>set('name',v)}/><Field label="Mobile Number" value={data.mobile} onChange={v=>set('mobile',v.replace(/\D/g,'').slice(0,10))} inputMode="numeric"/><Field label="Aadhaar / Farmer ID" value={data.farmerId} onChange={v=>set('farmerId',v)}/><Field label="Date of Birth" type="date" value={data.dob} onChange={v=>set('dob',v)}/><SelectField label="Gender" value={data.gender} onChange={v=>set('gender',v)} options={['Male','Female','Other']}/></div><div className="password-grid"><Field label="Password" type="password" value={data.password||''} onChange={v=>set('password',v)}/><Field label="Confirm Password" type="password" value={confirm} onChange={setConfirm}/></div></Section>}
    {step===1&&<Section title="Farm Details"><div className="grid2"><Field label="Address" value={data.address} onChange={v=>set('address',v)}/><Field label="Village" value={data.village} onChange={v=>set('village',v)}/><Field label="District" value={data.district} onChange={v=>set('district',v)}/><Field label="State" value={data.state} onChange={v=>set('state',v)}/><Field label="Land Area (Acres)" type="number" value={data.landArea} onChange={v=>set('landArea',v)}/><SelectField label="Land Ownership" value={data.ownership} onChange={v=>set('ownership',v)} options={['Owned','Leased','Shared']}/><SelectField label="Farmer Category" value={data.category} onChange={v=>set('category',v)} options={['Small Farmer','Marginal Farmer','Medium Farmer','Other']}/><Field label="Main Crop" value={data.mainCrop} onChange={v=>set('mainCrop',v)}/></div></Section>}
    {step===2&&<Section title="Bank Details"><div className="grid2"><Field label="Bank Account Details" value={data.bank} onChange={v=>set('bank',v)} placeholder="Account number or masked details"/><Field label="IFSC Code" value={data.ifsc} onChange={v=>set('ifsc',v.toUpperCase())}/></div><div className="info-box"><ShieldCheck size={18}/><span>Sensitive bank details are kept local in this demo and should be protected server-side in production.</span></div></Section>}
    {step===3&&<Section title="Required Documents"><div className="upload-grid">{fields.map(([display])=><div key={display}><FilePick display={display}/></div>)}</div><div className="muted note">Supported: PDF, JPG, PNG. Unsupported types are rejected.</div></Section>}
    {err&&<div className="error-box"><CircleAlert size={16}/>{err}</div>}<div className="register-actions"><button className="btn btn-ghost" disabled={step===0} onClick={()=>{setErr('');setStep(step-1)}}><ArrowLeft size={16}/> Back</button><button className="btn btn-primary" onClick={next}>{step===3?'Create Account':'Continue'} <ArrowRight size={16}/></button></div>
  </div></main></div>;
}
function Section({title,children}:{title:string;children:React.ReactNode}){return <section><h2 className="section-title">{title}</h2>{children}</section>}
function Field({label:fieldLabel,value,onChange,type='text',placeholder,inputMode}:{label:string;value:string;onChange:(v:string)=>void;type?:string;placeholder?:string;inputMode?:React.HTMLAttributes<HTMLInputElement>['inputMode']}){return <label>{fieldLabel}<input type={type} value={value} inputMode={inputMode} placeholder={placeholder} onChange={e=>onChange(e.target.value)}/></label>}
function SelectField({label:fieldLabel,value,onChange,options}:{label:string;value:string;onChange:(v:string)=>void;options:string[]}){return <label>{fieldLabel}<select value={value} onChange={e=>onChange(e.target.value)}><option value="">Select</option>{options.map(o=><option key={o}>{o}</option>)}</select></label>}
function Success(){const nav=useNavigate();return <div className="success-page"><div className="success-card"><div className="success-icon">✓</div><h1>Account Created Successfully</h1><p>Your farmer account has been created successfully.</p><button className="btn btn-primary btn-lg" onClick={()=>nav('/dashboard')}>Go to Dashboard <ArrowRight size={18}/></button></div></div>}

function Dashboard(){
  const location=useLocation(); const [open,setOpen]=useState(false); const [lang,setLang]=useState(read('kisanLang','en')); const [farmer,setFarmer]=useState<Farmer>(read('kisanFarmer',initialFarmer));
  const [geo,setGeo]=useState<{lat:number;lon:number}|null>(read('kisanGeo',null)); const [geoState,setGeoState]=useState<'idle'|'loading'|'done'|'denied'>('idle');
  const doGeo=()=>{if(!navigator.geolocation){setGeoState('denied');return}setGeoState('loading');navigator.geolocation.getCurrentPosition(p=>{const d={lat:p.coords.latitude,lon:p.coords.longitude};setGeo(d);save('kisanGeo',d);setGeoState('done')},()=>setGeoState('denied'),{enableHighAccuracy:true,timeout:10000});};
  useEffect(()=>{if(!geo)doGeo()},[]);
  const logout=()=>{save('kisanAuth',false);window.location.href='/login';};
  return <div className="app-shell"><Sidebar open={open} setOpen={setOpen} lang={lang}/><div className="overlay" style={{display:open?'block':''}} onClick={()=>setOpen(false)}></div><main className="main"><Topbar onMenu={()=>setOpen(true)} farmer={farmer} lang={lang} setLang={setLang} logout={logout}/><div className="content"><Routes>
    <Route index element={<DashboardHome farmer={farmer} geo={geo} doGeo={doGeo} refreshGeo={doGeo}/>}/>
    <Route path="account" element={<AccountPage farmer={farmer} setFarmer={setFarmer}/>}/>
    <Route path="documents" element={<DocumentsPage/>}/>
    <Route path="crops" element={<CropsPage farmer={farmer}/>}/>
    <Route path="markets" element={<MarketsPage/>}/>
    <Route path="calculator" element={<CalculatorPage/>}/>
    <Route path="finance" element={<FinancePage/>}/>
    <Route path="weather" element={<WeatherPage geo={geo}/>}/>
    <Route path="location" element={<MapsPage locationData={geo} geoState={geoState} locate={doGeo}/>}/>
    <Route path="logistics" element={<LogisticsPage geo={geo}/>}/>
    <Route path="schemes" element={<SchemesPage/>}/>
    <Route path="support" element={<SupportPage/>}/>
    <Route path="payments" element={<PaymentsPage/>}/>
    <Route path="*" element={<Navigate to="/dashboard" replace/>}/>
  </Routes></div></main></div>;
}
function navItems(lang:string){return [
  ['/',BarChart3,tr(lang,'dashboard')],['/account',User,tr(lang,'account')],['/api/documents',FileText,tr(lang,'documents')],['/crops',Leaf,tr(lang,'crops')],['/markets',BarChart3,tr(lang,'markets')],['/calculator',IndianRupee,tr(lang,'calculator')],['/finance',LineIcon,tr(lang,'finance')],['/weather',CloudSun,tr(lang,'weather')],['/location',MapPin,tr(lang,'location')],['/logistics',Truck,tr(lang,'logistics')],['/payments',CreditCard,tr(lang,'payments')],['/schemes',ShieldCheck,tr(lang,'schemes')],['/support',MessageCircle,tr(lang,'support')]
] as const;}
function Sidebar({open,setOpen,lang}:{open:boolean;setOpen:(v:boolean)=>void;lang:string}){const loc=useLocation();return <aside className={'sidebar '+(open?'open':'')}><div className="side-head"><Logo/><button className="icon-btn mobile-only" onClick={()=>setOpen(false)}><X size={19}/></button></div><div className="farmer-mini"><div className="avatar"><User/></div><div><strong>{read<Farmer>('kisanFarmer',initialFarmer).name}</strong><span>{read<Farmer>('kisanFarmer',initialFarmer).village}, {read<Farmer>('kisanFarmer',initialFarmer).district}</span></div></div><nav>{navItems(lang).map(([path,Icon,text])=><Link key={path} to={`/dashboard${path==='/'?'':path}`} onClick={()=>setOpen(false)} className={(loc.pathname===`/dashboard${path==='/'?'':path}`||loc.pathname.startsWith(`/dashboard${path}/`))?'active':''}><Icon size={18}/><span>{text}</span></Link>)}</nav></aside>}
function Topbar({onMenu,farmer,lang,setLang,logout}:{onMenu:()=>void;farmer:Farmer;lang:string;setLang:(v:string)=>void;logout:()=>void}){
  const [noticeOpen,setNoticeOpen]=useState(false);
  const notices=useMemo(()=>{const docs=read<any[]>('kisanDocs',[]);const crops=read<any[]>('kisanCropHistory',[]);const payments=read<any[]>('kisanPayments',[]);const out:any[]=[];if(crops[0])out.push({title:'Crop activity recorded',text:`${crops[0].crop}: ${crops[0].action}`});if(payments[0])out.push({title:'Payment status',text:`${payments[0].id}: ${payments[0].status}`});const pending=docs.filter((d:any)=>d.status==='Pending').length;if(pending)out.push({title:'Documents pending',text:`${pending} document(s) awaiting verification`});return out},[noticeOpen]);
  const goSearch=(value:string)=>{const v=value.toLowerCase();const map=v.includes('crop')?'crops':v.includes('market')||v.includes('price')?'markets':v.includes('payment')?'payments':v.includes('document')?'documents':v.includes('transport')?'logistics':v.includes('weather')?'weather':v.includes('account')?'account':'/' ;window.location.href=`/dashboard${map==='/'?'':`/${map}`}`};
  return <header className="topbar"><button className="icon-btn mobile-only" onClick={onMenu}><Menu/></button><div className="crumbs"><span>{APP_NAME}</span><b>/</b><strong>{farmer.name}</strong></div><div className="top-actions"><div className="top-search"><Search size={16}/><input aria-label="Search" placeholder="Search crops, markets, payments…" onKeyDown={e=>e.key==='Enter'&&goSearch(e.currentTarget.value)}/></div><div className="icon-notify"><button className="icon-btn" title="Notifications" onClick={()=>setNoticeOpen(v=>!v)}><Bell size={18}/></button>{noticeOpen&&<div className="notification-panel"><h3>{tr(lang,'notifications')}</h3>{notices.length?notices.map((n,i)=><div className="notification-item" key={i}><strong>{n.title}</strong><span>{n.text}</span></div>):<div className="notification-empty">No new notifications.</div>}</div>}</div><div className="lang-select"><Languages size={16}/><select aria-label={tr(lang,'language')} value={lang} onChange={e=>{setLang(e.target.value);save('kisanLang',e.target.value);window.dispatchEvent(new Event('kisan-language-change'))}}><option value="en">English</option><option value="hi">हिन्दी</option><option value="mr">मराठी</option><option value="bn">বাংলা</option><option value="gu">ગુજરાતી</option><option value="pa">ਪੰਜਾਬੀ</option><option value="ta">தமிழ்</option><option value="te">తెలుగు</option><option value="kn">ಕನ್ನಡ</option><option value="ml">മലയാളം</option><option value="or">ଓଡ଼ିଆ</option><option value="as">অসমীয়া</option></select></div><button className="icon-btn" onClick={logout} title={tr(lang,'logout')}><LogOut size={18}/></button><div className="profile-mini"><div className="avatar sm"><User size={16}/></div><div><strong>{farmer.name.split(' ')[0]}</strong><span>{tr(lang,'Farmer')}</span></div></div></div></header>
}

function DashboardHome({farmer,geo,doGeo,refreshGeo}:{farmer:Farmer;geo:{lat:number;lon:number}|null;doGeo:()=>void;refreshGeo:()=>void}){
  const [market,setMarket]=useState(marketPrices);
  const [updated,setUpdated]=useState(new Date());
  const refresh=async()=>{try{const r=await api.get('/market-prices');if(r.data?.prices?.length)setMarket(r.data.prices)}catch{}setUpdated(new Date())};
  const crops=read<any[]>('kisanCrops',[]).filter(c=>c.status!=='Archived');
  const lastCalc=read<any>('kisanLastCalculation',{});
  const activeCrops=crops.length;
  const highestMarket=market.length?Math.max(...market.map(m=>Number(m.price)||0)):0;
  const marketTop=[...market].sort((a,b)=>(Number(b.price)||0)-(Number(a.price)||0)).slice(0,4);
  const financeTotals=finance.reduce((s,f)=>({revenue:s.revenue+f.revenue,expenses:s.expenses+f.expenses,profit:s.profit+f.profit}),{revenue:0,expenses:0,profit:0});
  return <div className="page-section dashboard-reference">
    <div className="dash-head">
      <div><span className="eyebrow">Dashboard</span><h1>Welcome back, {farmer.name.split(' ')[0]}</h1><p>Monitor your crops, market prices and farm finances from one place.</p></div>
      <div className="head-actions"><button className="btn btn-soft" onClick={refresh}><RefreshCw size={16}/> Refresh</button><Link to="/dashboard/crops" className="btn btn-primary"><Plus size={17}/> Add Crop</Link></div>
    </div>

    <div className="kpi-grid reference-kpis">
      <KPI icon={<Leaf/>} title="Active Crops" value={String(activeCrops)} note="Current crop records"/>
      <KPI icon={<BarChart3/>} title="Highest Market Price" value={highestMarket?`₹${highestMarket.toLocaleString()}`:'—'} note="Latest available market signal"/>
      <KPI icon={<IndianRupee/>} title="Expected Revenue" value={lastCalc?.revenue!=null?`₹${Number(lastCalc.revenue).toLocaleString()}`:'—'} note="From saved calculation"/>
      <KPI icon={<TrendingUp/>} title="Estimated Profit" value={lastCalc?.result!=null?`₹${Number(lastCalc.result).toLocaleString()}`:'—'} note="From saved calculation"/>
    </div>

    <div className="reference-main-grid">
      <section className="panel reference-primary-panel">
        <PanelTitle title="Financial Overview" action={<Link className="link-btn" to="/dashboard/finance">View analysis <ArrowRight size={14}/></Link>}/>
        <div className="reference-panel-meta"><div><span>Total recorded revenue</span><strong>₹{financeTotals.revenue.toLocaleString()}</strong></div><div className="chart-legend"><span><i/> Revenue</span><span><i/> Expenses</span></div></div>
        <div className="reference-filters"><button className="filter-pill active">Overview</button><Link className="filter-pill" to="/dashboard/finance">Financial history <ArrowRight size={13}/></Link><span className="reference-updated"><Clock size={13}/> Updated {updated.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}</span></div>
        <div className="chart-box reference-chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={finance}><CartesianGrid strokeDasharray="3 3" vertical={false}/><XAxis dataKey="year"/><YAxis/><Tooltip formatter={(v:number)=>`₹${v.toLocaleString()}`}/><Area dataKey="revenue" name="Revenue" type="monotone" fillOpacity={0.16} strokeWidth={2.5}/><Area dataKey="expenses" name="Expenses" type="monotone" fillOpacity={0.08} strokeWidth={2}/></AreaChart></ResponsiveContainer></div>
      </section>

      <section className="panel reference-side-panel">
        <PanelTitle title="Market Snapshot" action={<Link className="link-btn" to="/dashboard/markets">View all <ArrowRight size={14}/></Link>}/>
        <div className="reference-side-stat"><span>Best available price</span><strong>{highestMarket?`₹${highestMarket.toLocaleString()}`:'—'}</strong><small>Across available market records</small></div>
        <div className="market-list-reference">{marketTop.map(m=><Link to="/dashboard/markets" className="market-row-reference" key={`${m.crop}-${m.market}`}><div><strong>{m.crop}</strong><span>{m.market}</span></div><div><b>₹{Number(m.price).toLocaleString()}</b><small className={m.change>=0?'positive':'negative'}>{m.change>=0?'+':''}{m.change}%</small></div><ArrowRight size={14}/></Link>)}</div>
        <div className="location-reference"><MapPin size={17}/><div><strong>{geo?'Current GPS location':'Location not available'}</strong><span>{geo?`${geo.lat.toFixed(3)}, ${geo.lon.toFixed(3)}`:'Use GPS to connect local context'}</span></div><button className="icon-btn" onClick={doGeo} title="Use current GPS"><Navigation size={15}/></button></div>
      </section>
    </div>

    <div className="reference-lower-grid">
      <section className="panel">
        <PanelTitle title="Crop Portfolio" action={<Link className="link-btn" to="/dashboard/crops">Manage crops <ArrowRight size={14}/></Link>}/>
        <div className="reference-table-wrap"><table className="reference-table"><thead><tr><th>Crop</th><th>Quantity</th><th>Status</th><th>Market</th><th></th></tr></thead><tbody>{crops.length?crops.slice(0,5).map((c:any)=><tr key={c.id||c.crop}><td><div className="table-primary"><span className="table-icon"><Leaf size={15}/></span><strong>{c.crop||'Crop'}</strong></div></td><td>{c.quantity||c.qty||'—'}</td><td><span className="status status-uploaded">Active</span></td><td>{c.market||'Not selected'}</td><td><Link to="/dashboard/crops" className="table-action">Open <ArrowRight size={13}/></Link></td></tr>):<tr><td colSpan={5}><div className="empty-state compact"><Leaf size={22}/><strong>No crop records yet.</strong><span>Add your first crop to see it here.</span></div></td></tr>}</tbody></table></div>
      </section>
      <section className="panel reference-actions-panel">
        <PanelTitle title="Quick Actions"/>
        <div className="reference-action-grid"><QuickAction icon={<Leaf/>} title="Add Crop" to="/dashboard/crops"/><QuickAction icon={<IndianRupee/>} title="Calculate Profit" to="/dashboard/calculator"/><QuickAction icon={<BarChart3/>} title="Compare Markets" to="/dashboard/markets"/><QuickAction icon={<Truck/>} title="Transport" to="/dashboard/logistics"/><QuickAction icon={<Upload/>} title="Documents" to="/dashboard/documents"/><QuickAction icon={<CreditCard/>} title="Payments" to="/dashboard/payments"/></div>
      </section>
    </div>

    <div className="reference-bottom-grid">
      <section className="panel">
        <PanelTitle title="Documents" action={<Link className="link-btn" to="/dashboard/documents">Manage <ArrowRight size={14}/></Link>}/>
        <div className="mini-docs">{defaultDocs.slice(0,4).map(d=><div key={d.name}><FileText size={16}/><span>{d.name}</span><b className={'status status-'+d.status.toLowerCase()}>{d.status}</b></div>)}</div>
      </section>
      <section className="panel">
        <PanelTitle title="Government Schemes" action={<Link className="link-btn" to="/dashboard/schemes">View schemes <ArrowRight size={14}/></Link>}/>
        <div className="scheme-mini-grid">{schemes.slice(0,2).map(s=><div key={s.name}><ShieldCheck size={19}/><strong>{s.name}</strong><span>{s.benefit}</span></div>)}</div>
      </section>
    </div>
  </div>;
}
function KPI({icon,title,value,note}:{icon:React.ReactNode;title:string;value:string;note:string}){return <div className="panel kpi"><div className="kpi-top"><div className="kpi-icon">{icon}</div><span>{title}</span></div><strong>{value}</strong><small>{note}</small></div>}
function PanelTitle({title,action}:{title:string;action?:React.ReactNode}){return <div className="panel-title"><strong>{title}</strong>{action}</div>}
function MetricChip({label,value}:{label:string;value:string}){return <div><span>{label}</span><strong>{value}</strong></div>}
function QuickAction({icon,title,to}:{icon:React.ReactNode;title:string;to:string}){return <Link to={to} className="quick-action"><span>{icon}</span><strong>{title}</strong><ArrowRight size={15}/></Link>}
function PageHeader({eyebrow,title,text,action}:{eyebrow:string;title:string;text:string;action?:React.ReactNode}){return <div className="page-header"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{text}</p></div>{action}</div>}

function AccountPage({farmer,setFarmer}:{farmer:Farmer;setFarmer:(f:Farmer)=>void}){const [draft,setDraft]=useState(farmer);const saveIt=()=>{setFarmer(draft);save('kisanFarmer',draft);alert('Account updated successfully.')};return <div className="page-section"><PageHeader eyebrow="My account" title="Farmer Profile" text="View and edit your farmer information."/><section className="panel"><div className="account-head"><div className="avatar xl"><User/></div><div><h2>{draft.name}</h2><p>{draft.village}, {draft.district}, {draft.state}</p></div></div><div className="grid2"><Field label="Name" value={draft.name} onChange={v=>setDraft({...draft,name:v})}/><Field label="Mobile Number" value={draft.mobile} onChange={v=>setDraft({...draft,mobile:v})}/><Field label="Address" value={draft.address} onChange={v=>setDraft({...draft,address:v})}/><Field label="Village" value={draft.village} onChange={v=>setDraft({...draft,village:v})}/><Field label="District" value={draft.district} onChange={v=>setDraft({...draft,district:v})}/><Field label="State" value={draft.state} onChange={v=>setDraft({...draft,state:v})}/></div><div className="form-actions"><button className="btn btn-primary" onClick={saveIt}><SaveIcon size={17}/> Save Changes</button><button className="btn btn-ghost" onClick={()=>setDraft(farmer)}>Cancel</button></div></section></div>}

function DocumentsPage(){
  const [state,setState]=useState<Doc[]>(read('kisanDocs',defaultDocs));
  const [busy,setBusy]=useState<string|null>(null); const [preview,setPreview]=useState<{name:string;url:string}|null>(null);
  const upload=async(name:string,f:File)=>{if(!['application/pdf','image/jpeg','image/png'].includes(f.type))return alert('Only PDF, JPG and PNG files are supported.');if(f.size>5*1024*1024)return alert('File must be 5 MB or smaller.');setBusy(name);try{const fd=new FormData();fd.append('document',f);fd.append('documentType',name);const r=await api.post('/api/documents',fd);const next=state.map(d=>d.name===name?{...d,file:f.name,status:'Uploaded' as const}:d);setState(next);save('kisanDocs',next);if(r.data?.file?.url)save(`doc-meta-${name}`,{...r.data.file,uploadedAt:new Date().toISOString()});}catch(e){alert('Upload failed. Please try again.')}finally{setBusy(null)}};
  const openFile=async(d:Doc)=>{if(!d.file)return alert('No file uploaded yet.');try{const key=`doc-meta-${d.name}`;const meta=read<any>(key,null);if(!meta?.url)return alert('Document preview is not available for this record yet.');const r=await fetch((import.meta.env.VITE_API_URL||'http://localhost:5000/api')+meta.url,{headers:{'x-demo-token':'demo-token'}});if(!r.ok)throw new Error();const blob=await r.blob();const url=URL.createObjectURL(blob);setPreview({name:d.file,url});}catch{alert('We could not open this document right now. Please try again.')}};
  const downloadFile=async(d:Doc)=>{try{const m=read<any>(`doc-meta-${d.name}`,null);if(!m?.url)return alert('Document download is not available yet.');const r=await fetch((import.meta.env.VITE_API_URL||'http://localhost:5000/api')+m.url,{headers:{'x-demo-token':'demo-token'}});if(!r.ok)throw new Error();const blob=await r.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=d.file||d.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch{alert('We could not download this document right now. Please try again.')}};
  const remove=async(d:Doc)=>{if(!confirm(`Delete ${d.name}?`))return;const meta=read<any>(`doc-meta-${d.name}`,null);if(meta?.filename){try{await api.delete(`/api/documents/${encodeURIComponent(meta.filename)}`,{headers:{'x-demo-token':'demo-token'}})}catch{}}localStorage.removeItem(`doc-meta-${d.name}`);const next=state.map(x=>x.name===d.name?{...x,file:undefined,status:'Pending' as const}:x);setState(next);save('kisanDocs',next);};
  return <div className="page-section"><PageHeader eyebrow="Farmer documents" title="Upload Documents" text="View, replace and track your farmer documents securely."/><div className="doc-grid">{state.map(d=>{const meta=read<any>(`doc-meta-${d.name}`,null);return <div className="panel doc-card animated-card" key={d.name}><div className="doc-card-top"><div className="doc-symbol big"><FileText/></div><span className={'status status-'+d.status.toLowerCase()}>{d.status}</span></div><h3>{d.name}</h3><p>{d.file||'No file selected yet.'}{meta?.size?` • ${(meta.size/1024).toFixed(0)} KB`:''}{meta?.uploadedAt?` • ${new Date(meta.uploadedAt).toLocaleDateString()}`:''}</p><div className="doc-card-actions"><label className="btn btn-soft btn-sm"><Upload size={15}/>{busy===d.name?'Uploading…':d.file?'Replace':'Upload'}<input type="file" accept=".pdf,.jpg,.jpeg,.png" hidden onChange={e=>{const f=e.target.files?.[0];if(f)upload(d.name,f)}}/></label>{d.file&&<><button className="btn btn-ghost btn-sm" onClick={()=>openFile(d)}><Eye size={15}/>View</button><button className="btn btn-ghost btn-sm" onClick={()=>downloadFile(d)}><DownloadIcon size={15}/>Download</button><button className="btn btn-ghost btn-sm danger" onClick={()=>remove(d)}><TrashIcon size={15}/>Delete</button></>}</div></div>})}</div>{preview&&<div className="modal-backdrop" onClick={()=>{URL.revokeObjectURL(preview.url);setPreview(null)}}><div className="modal-card" onClick={e=>e.stopPropagation()}><div className="modal-head"><div><strong>{preview.name}</strong><span>Private in-app preview</span></div><button className="icon-btn" onClick={()=>{URL.revokeObjectURL(preview.url);setPreview(null)}}><X/></button></div>{preview.url.match(/\.pdf($|\?)/i)||preview.name.toLowerCase().endsWith('.pdf')?<iframe className="doc-preview" title={preview.name} src={preview.url}/>:<img className="doc-preview-image" src={preview.url} alt={preview.name}/>}</div></div>}</div>}
function CropsPage({farmer}:{farmer:Farmer}){
  type CropRec={id:string;name:string;variety?:string;area:string;quantity:string;stage:string;health:string;location:string;plantingDate:string;harvestDate?:string;sellingDate?:string;sellingPrice?:string;buyer?:string;status:string;notes?:string};
  const seed=read<CropRec[]>('kisanCrops',[{id:'c1',name:farmer.mainCrop||'Soybean',variety:'JS 335',area:farmer.landArea||'5',quantity:'500',stage:'Flowering',health:'Good',location:`${farmer.village}, ${farmer.district}`,plantingDate:'2026-01-10',status:'Active',notes:''}]);
  const [crops,setCrops]=useState(seed); const [history,setHistory]=useState<any[]>(read('kisanCropHistory',[])); const [editing,setEditing]=useState<CropRec|null>(null);
  const [form,setForm]=useState({name:'',variety:'',area:'',quantity:'',status:'Active',notes:''});
  const lang=useLang();
  const persist=(next:CropRec[],activity?:any)=>{setCrops(next);save('kisanCrops',next);if(activity){const h=[{...activity,id:`h${Date.now()}`,date:new Date().toISOString()},...history];setHistory(h);save('kisanCropHistory',h)}};
  const reset=()=>setForm({name:'',variety:'',area:'',quantity:'',status:'Active',notes:''});
  const submit=()=>{if(!form.name.trim()||!(Number(form.area)>0))return alert('Enter crop name and a valid area.');if(editing){const nc={...editing,...form,quantity:form.quantity||editing.quantity};persist(crops.map(c=>c.id===editing.id?nc:c),{action:'Updated',crop:nc.name,quantity:nc.quantity,status:nc.status,location:nc.location,notes:nc.notes});setEditing(null)}else{const c:CropRec={id:`c${Date.now()}`,name:form.name.trim(),variety:form.variety,area:form.area,quantity:form.quantity||'0',stage:'Sown',health:'Not checked',location:`${farmer.village}, ${farmer.district}`,plantingDate:new Date().toISOString().slice(0,10),status:form.status,notes:form.notes};persist([...crops,c],{action:'Added',crop:c.name,quantity:c.quantity,status:c.status,location:c.location,notes:c.notes});}reset()};
  const edit=(c:CropRec)=>{setEditing(c);setForm({name:c.name,variety:c.variety||'',area:c.area,quantity:c.quantity,status:c.status,notes:c.notes||''})};
  const harvest=(c:CropRec)=>{const nc={...c,status:'Harvested',stage:'Harvested',harvestDate:new Date().toISOString().slice(0,10)};persist(crops.map(x=>x.id===c.id?nc:x),{action:'Harvested',crop:c.name,quantity:c.quantity,status:'Harvested',harvestDate:nc.harvestDate});};
  const sell=(c:CropRec)=>{const price=prompt('Selling price per kg',c.sellingPrice||'');if(price===null||!Number(price))return;const buyer=prompt('Buyer / market',c.buyer||'')||'Selected buyer/market';const nc={...c,status:'Sold',sellingDate:new Date().toISOString().slice(0,10),sellingPrice:price,buyer};persist(crops.map(x=>x.id===c.id?nc:x),{action:'Sold',crop:c.name,quantity:c.quantity,sellingPrice:price,status:'Sold',buyer,sellingDate:nc.sellingDate});};
  const updateQty=(c:CropRec)=>{const q=prompt('Update remaining quantity (kg)',c.quantity);if(q===null||Number(q)<0)return;const nc={...c,quantity:q};persist(crops.map(x=>x.id===c.id?nc:x),{action:'Quantity updated',crop:c.name,quantity:q,status:c.status});};
  return <div className="page-section"><PageHeader eyebrow="Crop management" title="Crops & Farm Activities" text="Manage active crops, harvests and sales without losing historical records."/><section className="quick-add panel"><div><h3>{editing?'Edit crop':'Add a crop'}</h3><p>Activity history is retained instead of overwritten.</p></div><div className="inline-form crop-entry-form"><input placeholder="Crop name" value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/><input placeholder="Variety" value={form.variety} onChange={e=>setForm({...form,variety:e.target.value})}/><input type="number" min="0" placeholder="Acres" value={form.area} onChange={e=>setForm({...form,area:e.target.value})}/><input type="number" min="0" placeholder="Quantity (kg)" value={form.quantity} onChange={e=>setForm({...form,quantity:e.target.value})}/><select value={form.status} onChange={e=>setForm({...form,status:e.target.value})}><option>Active</option><option>Harvested</option><option>Sold</option></select><input placeholder="Notes" value={form.notes} onChange={e=>setForm({...form,notes:e.target.value})}/><button className="btn btn-primary" onClick={submit}>{editing?<SaveIcon size={17}/>:<Plus size={17}/>} {editing?'Update Crop':tr(lang,'addCrop')}</button>{editing&&<button className="btn btn-ghost" onClick={()=>{setEditing(null);reset()}}>Cancel</button>}</div></section><div className="crop-grid">{crops.filter(c=>c.status!=='Archived').map((c,i)=><div className="panel crop-card animated-card" key={c.id}><div className="crop-art"><Leaf size={35}/></div><div className="crop-main"><span className="muted">Crop #{i+1} • {c.status}</span><h3>{c.name}</h3><p>{c.variety||'Variety not recorded'} • {c.area} acres • {c.quantity} kg</p><p>{c.location}</p><span className="status status-uploaded">{c.health}</span><div className="crop-actions"><button className="btn btn-soft btn-sm" onClick={()=>edit(c)}><Pencil size={14}/> Edit</button><button className="btn btn-soft btn-sm" onClick={()=>updateQty(c)}><Pencil size={14}/> Quantity</button><button className="btn btn-soft btn-sm" onClick={()=>harvest(c)} disabled={c.status==='Harvested'||c.status==='Sold'}>Harvest</button><button className="btn btn-soft btn-sm" onClick={()=>sell(c)} disabled={c.status==='Sold'}>Sell</button><button className="btn btn-ghost btn-sm danger" onClick={()=>{if(confirm('Archive this crop?'))persist(crops.map(x=>x.id===c.id?{...x,status:'Archived'}:x),{action:'Archived',crop:c.name,status:'Archived'})}}>Archive</button></div></div></div>)}</div><section className="panel history-panel"><PanelTitle title="Crop History"/><div className="history-list">{history.length===0?<div className="empty-state"><Leaf size={26}/><strong>No crop history yet.</strong><span>Your additions, updates, harvests and sales will appear here.</span><Link className="btn btn-soft btn-sm" to="/dashboard/crops">Add your first crop</Link></div>:history.map(h=><div className="history-row" key={h.id}><div><strong>{h.crop}</strong><span>{h.action} • {new Date(h.date).toLocaleString()}</span></div><div><b>{h.quantity||'—'} kg</b><span>{h.status||''}</span></div><div><b>{h.sellingPrice?`₹${h.sellingPrice}`:'—'}</b><span>{h.location||h.buyer||'—'}</span></div></div>)}</div></section></div>}

function MarketsPage(){
  const [rows,setRows]=useState(marketPrices); const [updated,setUpdated]=useState<Date|null>(null); const [search,setSearch]=useState(''); const [range,setRange]=useState('1M'); const [loading,setLoading]=useState(false);
  const [listing,setListing]=useState(read('kisanProduceListing',{crop:'Soybean',quantity:'10',location:'Ralegaon, Wardha',expectedPrice:'4850'}));
  const refresh=async()=>{setLoading(true);try{const r=await api.get('/market-prices');if(Array.isArray(r.data?.prices)&&r.data.prices.length)setRows(r.data.prices);if(r.data?.lastUpdated)setUpdated(new Date(r.data.lastUpdated));else setUpdated(new Date())}catch{setUpdated(new Date())}finally{setLoading(false)}};
  useEffect(()=>{refresh()},[]);
  const filtered=rows.filter(m=>m.crop.toLowerCase().includes(search.toLowerCase())||m.market.toLowerCase().includes(search.toLowerCase()));
  const publish=()=>{if(!listing.crop||!(Number(listing.quantity)>0)||!listing.location)return alert('Enter crop, quantity and location.');save('kisanProduceListing',listing);alert('Produce listing saved. No buyer offer is created unless an approved buyer connector is configured.')};
  const selected=filtered[0]||rows[0]; const second=filtered[1]||rows.find(x=>x.market!==selected?.market)||selected;
  const transportFor=(crop:string,market:string)=>{const hit=logistics.find(x=>market.toLowerCase().includes(x.name.toLowerCase()));return hit?.cost|| (crop==='Soybean'?440:980)};
  const netFor=(m:any)=>Math.max(0,m.price-transportFor(m.crop,m.market));
  return <div className="page-section"><PageHeader eyebrow="Price discovery" title="Market Linkage & Price Discovery" text="Compare price, transport cost and estimated net return before choosing where to sell." action={<button className="btn btn-soft" onClick={refresh} disabled={loading}>{loading?<RefreshCw className="spin" size={16}/>:<RefreshCw size={16}/>} {loading?'Loading…':'Refresh'}</button>}/><section className="panel market-linkage-card"><div><PanelTitle title="Farmer → Market connection"/><p className="panel-copy">List produce details for an approved buyer connector. This build does not invent buyer offers.</p></div><div className="listing-form grid2"><Field label="Crop" value={listing.crop} onChange={v=>setListing({...listing,crop:v})}/><Field label="Quantity (qtl)" type="number" value={listing.quantity} onChange={v=>setListing({...listing,quantity:v})}/><Field label="Pickup location" value={listing.location} onChange={v=>setListing({...listing,location:v})}/><Field label="Expected price / qtl" type="number" value={listing.expectedPrice} onChange={v=>setListing({...listing,expectedPrice:v})}/></div><button className="btn btn-primary" onClick={publish}><Package size={17}/> Save produce listing</button></section><div className="market-tools panel"><div className="input-wrap"><Search size={18}/><input placeholder="Search crop or market" value={search} onChange={e=>setSearch(e.target.value)}/></div><span className="muted">Source: backend market adapter • {updated?`Last updated ${updated.toLocaleTimeString()}`:'Update time unavailable'}</span></div><section className="panel"><PanelTitle title="Smart market comparison"/><div className="market-compare-grid">{[selected,second].filter(Boolean).map((m:any,i:number)=>{const transport=transportFor(m.crop,m.market);const net=netFor(m);return <div className={'compare-card '+(i===0?'recommended':'')} key={`${m.market}-${i}`}><span className="eyebrow">Market {i===0?'A':'B'} {i===0?'• Current selection':''}</span><h3>{m.market}</h3><p>{m.crop}</p><div className="compare-row"><span>Expected price</span><strong>₹{m.price.toLocaleString()} / qtl</strong></div><div className="compare-row"><span>Transport estimate</span><strong>₹{transport.toLocaleString()}</strong></div><div className="compare-row"><span>Estimated net return</span><strong>₹{net.toLocaleString()}</strong></div>{i===0&&<b className="recommend-badge">Potentially better net return</b>}</div>})}</div><div className="info-box"><ShieldCheck size={18}/><span>Net return = indicative selling price − estimated transport. Charges and verified market data are required before a real sale decision.</span></div></section><section className="section-grid two"><div className="market-table panel"><div className="table-head"><span>Crop</span><span>Market</span><span>Price</span><span>Change</span><span>Net return</span></div>{filtered.length===0?<div className="empty-state"><Search size={26}/><strong>No matching market data.</strong><span>Try another crop or market name.</span></div>:filtered.map((m:any)=><div className="table-row" key={`${m.crop}-${m.market}`}><strong>{m.crop}</strong><span>{m.market}</span><span>₹{m.price.toLocaleString()} / qtl</span><span className={m.change>=0?'positive':'negative'}>{m.change>=0?'+':''}{m.change}%</span><span><b>₹{netFor(m).toLocaleString()}</b><small> after estimated transport</small></span></div>)}</div><section className="panel"><div className="market-chart-head"><div><PanelTitle title="Price trend"/><span className="muted">Trend is shown only when the provider supplies historical observations.</span></div><div className="range-pills">{['1M','3M','1Y','3Y'].map(r=><button key={r} className={range===r?'active':''} onClick={()=>setRange(r)}>{r}</button>)}</div></div><div className="chart-box"><div className="empty-state chart-empty"><LineIcon size={28}/><strong>Historical series not available</strong><span>Connect a verified historical price feed to plot {range} data.</span></div></div></section></section><div className="panel info-box"><ShieldCheck size={18}/><span>Market source and freshness are always shown. Demo rows are not represented as live government/mandi data.</span></div></div>}

function CalculatorPage(){
  const empty={crop:'',area:'',expectedYield:'',actualYield:'',quantity:'',price:'',seed:'',fertilizer:'',pesticide:'',labour:'',irrigation:'',electricity:'',machinery:'',other:'',harvest:'',cleaning:'',sorting:'',packaging:'',storage:'',loading:'',wastage:'0',distance:'',transportType:'Truck',transport:'',loadingTransport:'',otherTransport:'',market:'',quantitySold:'',sellingPrice:'',commission:'',marketCharges:'',deductions:''};
  const [v,setV]=useState(empty); const [savedAt,setSavedAt]=useState(''); const n=(k:keyof typeof v)=>Number(v[k])||0; const production=['seed','fertilizer','pesticide','labour','irrigation','electricity','machinery','other'].reduce((s,k)=>s+n(k as keyof typeof v),0); const harvest=['harvest','cleaning','sorting','packaging','storage','loading'].reduce((s,k)=>s+n(k as keyof typeof v),0); const transport=n('transport')+n('loadingTransport')+(n('distance')*0); const selling=['commission','marketCharges','deductions'].reduce((s,k)=>s+n(k as keyof typeof v),0); const qtySold=n('quantitySold')||n('quantity')||n('actualYield')||n('expectedYield'); const gross=qtySold*n('sellingPrice')||n('price')*(n('actualYield')||n('expectedYield')); const total=production+harvest+transport+selling; const net=gross-total; const profitPerKg=qtySold?net/qtySold:0; const margin=gross?net/gross*100:0; const breakEven=qtySold?total/qtySold:0; const roi=total?net/total*100:0; const set=(k:keyof typeof v,x:string)=>setV({...v,[k]:x}); const saveCalc=async()=>{try{await api.post('/calculations', {...v,totalExpenses:total,revenue:gross,result:net,metrics:{profitPerKg,margin,breakEven,roi}})}catch{}save('kisanLastCalculation',{...v,totalExpenses:total,revenue:gross,result:net,metrics:{profitPerKg,margin,breakEven,roi}});setSavedAt(new Date().toLocaleTimeString())};
  const group=(title:string,keys:[keyof typeof v,string][]) => <section className="calc-group"><h3>{title}</h3><div className="grid2">{keys.map(([k,l])=><div key={String(k)}><Field label={l} value={v[k]} onChange={x=>set(k,x)} type={['crop','transportType','market'].includes(String(k))?'text':'number'}/></div>)}</div></section>;
  return <div className="page-section"><PageHeader eyebrow="Farm economics" title="Smart Profit Calculator" text="See production, post-harvest, transport and selling costs before you choose a market."/><section className="panel calculator"><div className="calculator-grid"><div>{group('Production Costs',[['crop','Crop'],['area','Area (Acres)'],['expectedYield','Expected Yield (kg)'],['actualYield','Actual Yield (kg)'],['quantity','Quantity (kg)'],['price','Expected Price / unit'],['seed','Seed Cost'],['fertilizer','Fertilizer Cost'],['pesticide','Pesticide / Inputs'],['labour','Labour Cost'],['irrigation','Irrigation Cost'],['electricity','Electricity / Fuel'],['machinery','Machinery / Equipment'],['other','Other Farming Expenses']])}{group('Harvest & Post-Harvest',[['harvest','Harvesting Cost'],['cleaning','Cleaning Cost'],['sorting','Sorting / Grading'],['packaging','Packaging'],['storage','Storage'],['loading','Loading / Unloading'],['wastage','Wastage %']])}{group('Transportation',[['distance','Distance (km)'],['transport','Transport Cost'],['loadingTransport','Other Transport Charges']])}{group('Selling',[['market','Market / Buyer'],['quantitySold','Quantity Sold (kg)'],['sellingPrice','Selling Price / kg'],['commission','Commission'],['marketCharges','Market Charges'],['deductions','Other Deductions']])}<div className="form-actions"><button className="btn btn-primary" onClick={saveCalc}><SaveIcon size={17}/> Save Calculation</button><button className="btn btn-ghost" onClick={()=>setV(empty)}>Reset</button>{savedAt&&<span className="muted">Saved {savedAt}</span>}</div></div><div className="result-card sticky-result"><div className="result-heading"><span>Financial Result</span><strong>{net>=0?'Estimated Net Profit':'Estimated Net Loss'}</strong></div><div className="result-row"><span>Gross Revenue</span><strong>₹{gross.toLocaleString(undefined,{maximumFractionDigits:0})}</strong></div><div className="result-row"><span>Production Costs</span><strong>₹{production.toLocaleString()}</strong></div><div className="result-row"><span>Harvest / Post-Harvest</span><strong>₹{harvest.toLocaleString()}</strong></div><div className="result-row"><span>Transport Costs</span><strong>₹{transport.toLocaleString()}</strong></div><div className="result-row"><span>Selling Charges</span><strong>₹{selling.toLocaleString()}</strong></div><div className="result-row highlight"><span>Net {net>=0?'Profit':'Loss'}</span><strong>₹{Math.abs(net).toLocaleString(undefined,{maximumFractionDigits:0})}</strong></div><div className="metric-grid"><MetricChip label="Cost / kg" value={`₹${(qtySold?total/qtySold:0).toFixed(2)}`}/><MetricChip label="Net / kg" value={`₹${profitPerKg.toFixed(2)}`}/><MetricChip label="Margin" value={`${margin.toFixed(1)}%`}/><MetricChip label="Break-even" value={`₹${breakEven.toFixed(2)}`}/><MetricChip label="ROI" value={`${roi.toFixed(1)}%`}/></div></div></div></section></div>}
function FinancePage(){
  const [period,setPeriod]=useState<'yearly'|'monthly'>('yearly'); const [year,setYear]=useState('2026'); const [month,setMonth]=useState('April');
  const totalRevenue=finance.reduce((s,f)=>s+f.revenue,0),totalExpenses=finance.reduce((s,f)=>s+f.expenses,0),totalProfit=finance.reduce((s,f)=>s+f.profit,0);
  return <div className="page-section"><PageHeader eyebrow="Financial history" title="3-Year & Monthly Financial Analysis" text="Review recorded financial history. Missing months are shown as unavailable rather than invented."/><div className="period-tools panel"><div className="range-pills"><button className={period==='yearly'?'active':''} onClick={()=>setPeriod('yearly')}>Yearly</button><button className={period==='monthly'?'active':''} onClick={()=>setPeriod('monthly')}>Monthly</button></div>{period==='yearly'?<select value={year} onChange={e=>setYear(e.target.value)}><option>2026</option><option>2025</option><option>2024</option></select>:<><select value={year} onChange={e=>setYear(e.target.value)}><option>2026</option><option>2025</option><option>2024</option></select><select value={month} onChange={e=>setMonth(e.target.value)}>{['January','February','March','April','May','June','July','August','September','October','November','December'].map(m=><option key={m}>{m}</option>)}</select></>}</div><div className="kpi-grid"><KPI icon={<Wallet/>} title="Revenue" value={`₹${period==='yearly'?finance.find(f=>f.year===year)?.revenue?.toLocaleString()||'—':'—'}`} note={period==='yearly'?'Selected year':'No monthly record'}/><KPI icon={<TrendingDown/>} title="Expenses" value={`₹${period==='yearly'?finance.find(f=>f.year===year)?.expenses?.toLocaleString()||'—':'—'}`} note={period==='yearly'?'Selected year':'No monthly record'}/><KPI icon={<TrendingUp/>} title="Profit" value={`₹${period==='yearly'?finance.find(f=>f.year===year)?.profit?.toLocaleString()||'—':'—'}`} note={period==='yearly'?'Selected year':'No monthly record'}/><KPI icon={<Activity/>} title="3-year total profit" value={`₹${totalProfit.toLocaleString()}`} note="Recorded annual history"/></div>{period==='monthly'?<section className="panel"><div className="empty-state"><CalendarIcon size={28}/><strong>No monthly data available for {month} {year}.</strong><span>Connect farm records to enable month-by-month comparisons. No synthetic history is shown.</span></div></section>:<section className="panel"><PanelTitle title="Revenue vs Expenses vs Profit"/><div className="chart-box large"><ResponsiveContainer width="100%" height="100%"><BarChart data={finance}><CartesianGrid strokeDasharray="3 3" vertical={false}/><XAxis dataKey="year"/><YAxis/><Tooltip/><Legend/><Bar dataKey="revenue" name="Revenue" radius={[6,6,0,0]}/><Bar dataKey="expenses" name="Expenses" radius={[6,6,0,0]}/><Bar dataKey="profit" name="Profit" radius={[6,6,0,0]}/></BarChart></ResponsiveContainer></div></section>}</div>}
function WeatherPage({ geo }: { geo: { lat: number; lon: number } | null }) {
  const [data,setData]=useState<any>(null); const [loading,setLoading]=useState(false); const [error,setError]=useState(''); const [updated,setUpdated]=useState<Date|null>(null);
  const fetchWeather=async()=>{if(!geo){setError('Location is not available yet. Use current GPS first.');return}setLoading(true);setError('');try{const url=`https://api.open-meteo.com/v1/forecast?latitude=${geo.lat}&longitude=${geo.lon}&current=temperature_2m,relative_humidity_2m,wind_speed_10m,weather_code&hourly=temperature_2m,relative_humidity_2m,wind_speed_10m,precipitation_probability&forecast_days=1&timezone=auto`;const r=await fetch(url);if(!r.ok)throw new Error();const j=await r.json();setData(j);setUpdated(new Date())}catch{setError('We could not load live weather right now. Please try again.')}finally{setLoading(false)}};
  useEffect(()=>{fetchWeather()},[geo?.lat,geo?.lon]); const current=data?.current; const weatherText=(code:number)=>code===0?'Clear':code<4?'Partly cloudy':code<50?'Cloudy':code<70?'Rain likely':'Weather changes expected'; const hourly=data?.hourly?.time?.slice(0,4)||[];
  return <div className="page-section"><PageHeader eyebrow="Current weather" title="Weather for the Farmer" text="Weather uses the current GPS coordinates when permission is available." action={<button className="btn btn-soft" onClick={fetchWeather} disabled={loading}>{loading?<RefreshCw className="spin" size={16}/>:<RefreshCw size={16}/>} {loading?'Loading…':'Refresh'}</button>}/>{error&&<div className="error-box"><CircleAlert size={16}/>{error}<button className="btn btn-soft btn-sm" onClick={fetchWeather}>Retry</button></div>}<div className="weather-grid"><section className="panel"><div className="weather-sky"><CloudSun size={72}/><div><strong>{current?`${Math.round(current.temperature_2m)}°C`:'31°C'}</strong><span>{current?weatherText(current.weather_code):'Fallback weather'}</span></div></div><div className="weather-stat-grid"><MiniMetric icon={<Activity/>} name="Humidity" value={current?`${current.relative_humidity_2m}%`:'70%'}/><MiniMetric icon={<Wind/>} name="Wind" value={current?`${Math.round(current.wind_speed_10m)} km/h`:'12 km/h'}/><MiniMetric icon={<CloudSun/>} name="Rain chance" value={data?.hourly?.precipitation_probability?.[0]!=null?`${data.hourly.precipitation_probability[0]}%`:'20%'}/><MiniMetric icon={<Leaf/>} name="Weather code" value={current?String(current.weather_code):'—'}/></div><div className="forecast-row">{hourly.map((t:string,i:number)=><div key={t}><span>{new Date(t).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}</span><strong>{Math.round(data.hourly.temperature_2m[i])}°C</strong></div>)}</div></section><section className="panel"><PanelTitle title="Location context"/><div className="location-summary"><MapPin size={36}/><div><strong>{geo?`${geo.lat.toFixed(4)}, ${geo.lon.toFixed(4)}`:'GPS not available'}</strong><span>{geo?'Weather is linked to the captured GPS point.':'Allow location access to use current weather.'}</span></div></div><div className="info-box"><ShieldCheck size={18}/><span>Source: Open-Meteo. {updated?`Last updated ${updated.toLocaleTimeString()}.`:'Waiting for data.'}</span></div></section></div></div>
}
type MiniMetricProps = {
  icon: React.ReactNode;
  name: string;
  value: string;
};

function MiniMetric({ icon, name, value }: MiniMetricProps) {
  return (
    <div>
      <div>{icon}</div>
      <span>{name}</span>
      <strong>{value}</strong>
    </div>
  );
}
function MapsPage({locationData,geoState,locate}:{locationData:{lat:number;lon:number}|null;geoState:string;locate:()=>void}){const [manualLocation,setManualLocation]=useState('Wardha, Maharashtra');const query=locationData?`${locationData.lat},${locationData.lon}`:manualLocation.trim()||'Wardha, Maharashtra';return <div className="page-section"><PageHeader eyebrow="GPS & Google Maps" title="Current Location" text="Use browser GPS to locate the farmer and open the point in Google Maps." action={<button className="btn btn-primary" onClick={locate}><Navigation size={17}/> Use Current GPS</button>}/><div className="map-grid"><section className="panel"><div className="map-top"><div><span className="muted">GPS status</span><strong>{geoState==='done'||locationData?'Location captured':geoState==='loading'?'Requesting permission…':geoState==='denied'?'Permission denied':'Waiting for permission'}</strong></div></div><div className="coords"><div><span>Latitude</span><strong>{locationData?.lat.toFixed(6)||'—'}</strong></div><div><span>Longitude</span><strong>{locationData?.lon.toFixed(6)||'—'}</strong></div></div>{geoState==='denied'&&<div className="error-box">Location permission was denied or unavailable. The website continues working. Use the map manually or enable permission.</div>}<div className="map-frame"><iframe title="Google Maps" src={`https://www.google.com/maps?q=${encodeURIComponent(query)}&z=13&output=embed`} loading="lazy"/></div><a className="btn btn-soft" href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`} target="_blank" rel="noreferrer"><Globe2 size={17}/> Open in Google Maps</a></section><section className="panel"><PanelTitle title="Nearby services"/><div className="service-list"><Service icon={<Package/>} title="APMC Markets" value="Compare nearby mandis"/><Service icon={<Tractor/>} title="Farm inputs" value="Seeds • fertilizers • pesticides"/><Service icon={<Users/>} title="Buyer discovery" value="Market linkage ready"/><Service icon={<ShieldCheck/>} title="Government offices" value="Scheme & document support"/></div><div className="manual-location"><label>Manual location fallback<input value={manualLocation} onChange={e=>setManualLocation(e.target.value)} placeholder="Village, District or market"/></label><span className="muted">Use this when GPS permission is denied.</span></div><div className="info-box"><MapPin size={18}/><span>GPS is used when available; otherwise this manual location drives the map link.</span></div></section></div></div>}
function Service({icon,title,value}:{icon:React.ReactNode;title:string;value:string}){return <div className="service-row"><div className="feature-icon">{icon}</div><div><strong>{title}</strong><span>{value}</span></div><ArrowRight size={15}/></div>}
function LogisticsPage({geo}:{geo:{lat:number;lon:number}|null}){const [qty,setQty]=useState('20');const [destination,setDestination]=useState('Hinganghat APMC');const [optimized,setOptimized]=useState(false);const factor=Math.max(1,Number(qty)||1);const base=55*8;const shared=optimized?Math.round(base*0.25):0;const estimated=Math.max(0,base-shared);return <div className="page-section"><PageHeader eyebrow="Transport optimization" title="Logistics & Delivery" text="Estimate cost, compare routes and track static/estimated delivery status."/><div className="section-grid two"><section className="panel"><PanelTitle title="Transport Cost Optimizer"/><div className="grid2"><Field label="Pickup" value={geo?`${geo.lat.toFixed(3)}, ${geo.lon.toFixed(3)}`:'Current farm / manual location'} onChange={()=>{}}/><Field label="Destination" value={destination} onChange={setDestination}/><Field label="Load / Quantity" type="number" value={qty} onChange={setQty}/><Field label="Cost per km" value="₹8" onChange={()=>{}}/></div><div className="optimizer-card"><div><span>Estimated distance</span><strong>55 km</strong></div><div><span>Estimated base cost</span><strong>₹{(base*factor/20).toLocaleString()}</strong></div><div><span>Potential shared-transport saving</span><strong>₹{(shared*factor/20).toLocaleString()}</strong></div><div className="highlight"><span>Estimated total</span><strong>₹{(estimated*factor/20).toLocaleString()}</strong></div></div><button className="btn btn-primary" onClick={()=>setOptimized(true)}><RouteIcon size={17}/> Find lower-cost option</button></section><section className="panel"><PanelTitle title="Transport status"/><div className="timeline"><Step title="Pickup planned" done/><Step title="In transit" done={optimized}/><Step title="Delivered" done={false}/></div><div className="info-box"><Clock size={18}/><span>ETA is estimated only in this runnable build. No real-time tracking is claimed.</span></div></section></div><section className="panel"><PanelTitle title="Route cost graph"/><div className="chart-box large"><ResponsiveContainer width="100%" height="100%"><BarChart data={logistics}><CartesianGrid strokeDasharray="3 3" vertical={false}/><XAxis dataKey="name"/><YAxis/><Tooltip/><Legend/><Bar dataKey="cost" name="Transport Cost (₹)" radius={[7,7,0,0]}/></BarChart></ResponsiveContainer></div></section></div>}
function Step({title,done}:{title:string;done:boolean}){return <div className={'timeline-step '+(done?'done':'')}><div className="timeline-dot">{done?<Check size={15}/>:<span/>}</div><strong>{title}</strong></div>}

function PaymentsPage(){const [method,setMethod]=useState('UPI');const [amount,setAmount]=useState('5000');const [status,setStatus]=useState<'Idle'|'Pending'|'Processing'|'Successful'|'Failed'|'Refunded'>('Idle');const [txn,setTxn]=useState('');const [copied,setCopied]=useState(false);const [history,setHistory]=useState<any[]>(read('kisanPayments',[]));const upi=`upi://pay?pa=nyxaro@ptyes&pn=Kisan%20Setu&am=${encodeURIComponent(Number(amount||0).toFixed(2))}&cu=INR&tn=${encodeURIComponent('Kisan Setu payment')}`;const pay=async()=>{if(!(Number(amount)>0))return alert('Enter a valid amount.');setStatus('Pending');try{const r=await api.post('/payments/create',{amount:Number(amount),method,reference:`KS-${Date.now()}`});const id=r.data?.payment?.id||`KS${Date.now().toString().slice(-8)}`;setTxn(id);setStatus('Pending');setHistory(h=>[r.data?.payment||{id,amount:Number(amount),method,status:'Pending' as const,createdAt:new Date().toISOString()},...h]);save('kisanPayments',r.data?.payment?[r.data.payment,...history]:history)}catch{setStatus('Failed')}};const copy=()=>{navigator.clipboard?.writeText('nyxaro@ptyes');setCopied(true);setTimeout(()=>setCopied(false),1400)};return <div className="page-section"><PageHeader eyebrow="Payments" title="UPI Payment & Tracking" text="Simple farmer-friendly UPI payment setup. A displayed QR is not treated as payment confirmation."/><div className="section-grid two"><section className="panel"><PanelTitle title="Payment details"/><div className="grid2"><Field label="Order / Crop" value="Farmer transaction" onChange={()=>{}}/><Field label="Amount (₹)" type="number" value={amount} onChange={setAmount}/></div><div className="upi-box payment-card"><div className="qr-real"><QRCodeSVG value={upi} size={150} includeMargin/></div><div><span className="eyebrow">UPI ID</span><strong>nyxaro@ptyes</strong><p>Scan the QR or open a UPI app. You can also copy the UPI ID.</p><div className="payment-actions"><button className="btn btn-soft" onClick={copy}>{copied?<CheckCheck size={16}/>:<Copy size={16}/>} {copied?'Copied':'Copy UPI ID'}</button><a className="btn btn-soft" href={upi}>Open UPI app</a></div><button className="btn btn-primary" onClick={pay} disabled={status==='Pending'||status==='Processing'}><CircleDollarSign size={17}/> Create Payment ₹{Number(amount||0).toLocaleString()}</button></div></div></section><section className="panel"><PanelTitle title="Payment tracking"/><div className="payment-timeline"><Step title="Payment Created" done={!!txn}/><Step title="Payment Initiated" done={status==='Processing'||status==='Successful'}/><Step title="Payment Processing" done={status==='Processing'||status==='Successful'}/><Step title="Payment Confirmed" done={status==='Successful'}/><Step title="Order Completed" done={status==='Successful'}/></div><div className={'payment-status '+status.toLowerCase()}><span>Status</span><strong>{status}</strong>{txn&&<div className="txn"><span>Transaction Reference</span><b>{txn}</b></div>}<div className="txn"><span>Amount</span><b>₹{Number(amount||0).toLocaleString()}</b></div><div className="txn"><span>Method</span><b>{method}</b></div><div className="txn"><span>Date / time</span><b>{new Date().toLocaleString()}</b></div>{txn&&<div className="payment-actions"><button className="btn btn-soft btn-sm" onClick={async()=>{setStatus('Processing');try{const r=await api.post(`/payments/${txn}/verify`);setStatus(r.data?.payment?.status||'Pending')}catch{setStatus('Pending')}}}><RefreshCw size={14}/> Check verification</button><button className="btn btn-ghost btn-sm" onClick={()=>{const receipt=`Kisan Setu payment\nReference: ${txn}\nAmount: ₹${Number(amount||0).toLocaleString()}\nStatus: ${status}`;navigator.clipboard?.writeText(receipt)}}><Copy size={14}/> Copy receipt</button></div>}</div><div className="info-box"><ShieldCheck size={18}/><span>Pending means payment still requires provider/bank confirmation. This demo never marks a QR display as successful.</span></div></section></div><section className="panel"><PanelTitle title="Recent payments"/><div className="history-list">{history.length===0?<div className="empty-state"><CreditCard size={26}/><strong>No transactions yet.</strong><span>Created payments will appear here.</span></div>:history.slice(0,6).map((p:any)=><div className="history-row" key={p.id}><div><strong>{p.id}</strong><span>{p.method} • {new Date(p.createdAt||Date.now()).toLocaleString()}</span></div><div><b>₹{Number(p.amount||0).toLocaleString()}</b><span>{p.status}</span></div></div>)}</div></section></div>}
function SchemesPage(){return <div className="page-section"><PageHeader eyebrow="Farmer welfare" title="Government Schemes" text="Learn about relevant schemes and visit official government pages."/><div className="scheme-grid">{schemes.map(s=><div className="panel scheme-card" key={s.name}><div className="scheme-card-head"><div className="scheme-logo"><ShieldCheck size={20}/></div><span>Official link</span></div><h3>{s.name}</h3><p>{s.desc}</p><div className="scheme-copy"><div><b>Eligibility</b><span>{s.eligibility}</span></div><div><b>Benefits</b><span>{s.benefit}</span></div></div><a className="btn btn-soft" href={s.url} target="_blank" rel="noreferrer">Apply / Learn More <ArrowRight size={15}/></a></div>)}</div></div>}
function SupportPage(){return <div className="page-section"><PageHeader eyebrow="Farmer support" title="WhatsApp Support" text="Reach support quickly from your phone or desktop."/><section className="panel support-main"><div className="wa-badge large"><MessageCircle size={36}/></div><div><h2>Chat with Support on WhatsApp</h2><p>Ask us about market prices, schemes, documents, logistics or the profit calculator.</p><a className="btn btn-primary btn-lg" href="https://wa.me/919876543210?text=Hello%20Kisan%20Setu%20Support%2C%20I%20need%20help." target="_blank" rel="noreferrer"><MessageCircle size={18}/> Open WhatsApp</a></div></section></div>}

export default App;
